package com.trakio.core.files;

import com.trakio.core.config.TrakioProperties;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

@Component
class LocalFileStorage implements FileStorage {

    /** Keys are generated by us; this guards against path traversal if that ever changes. */
    private static final Pattern KEY = Pattern.compile("[a-f0-9]{32}");

    private final Path root;

    LocalFileStorage(TrakioProperties properties) throws IOException {
        this.root = Path.of(properties.storage().localDir()).toAbsolutePath().normalize();
        Files.createDirectories(root);
    }

    private Path resolve(String key) {
        if (!KEY.matcher(key).matches()) {
            throw new IllegalArgumentException("Invalid storage key");
        }
        return root.resolve(key.substring(0, 2)).resolve(key);
    }

    @Override
    public void write(String key, byte[] data) throws IOException {
        Path path = resolve(key);
        Files.createDirectories(path.getParent());
        Files.write(path, data, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
    }

    @Override
    public InputStream read(String key) throws IOException {
        return Files.newInputStream(resolve(key));
    }

    @Override
    public void delete(String key) throws IOException {
        Files.deleteIfExists(resolve(key));
    }
}
